CREATE TABLE work_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,person_id BIGINT UNSIGNED NOT NULL,territory_uf CHAR(2) NOT NULL,title VARCHAR(200) NOT NULL,details TEXT NOT NULL,status ENUM('aberto','concluido') NOT NULL DEFAULT 'aberto',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(territory_uf)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE outbox (id CHAR(32) PRIMARY KEY,event_type VARCHAR(64) NOT NULL,payload JSON NOT NULL,delivered_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(delivered_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
